public final class IngestionJobResponse {private final String jobId,documentId,documentVersionId,errorCode,errorMessage,statisticsJson;private final IngestionStatus status;private final int progress,attempt;public IngestionJobResponse(IngestionJob v){jobId=v.getId();documentId=v.getDocumentId();documentVersionId=v.getDocumentVersionId();status=v.getStatus();progress=v.getProgress();attempt=v.getAttempt();errorCode=v.getErrorCode();errorMessage=v.getErrorMessage();statisticsJson=v.getStatisticsJson();}public String getJobId(){return jobId;}public String getDocumentId(){return documentId;}public String getDocumentVersionId(){return documentVersionId;}public IngestionStatus getStatus(){return status;}public int getProgress(){return progress;}public int getAttempt(){return attempt;}public String getErrorCode(){return errorCode;}public String getErrorMessage(){return errorMessage;}public String getStatisticsJson(){return statisticsJson;}}
